/**
 * mmm — Mixture Markov Model clustering (basic deterministic EM).
 *
 * Pure-TypeScript, zero-dependency port of R `Nestimate:::.mmm_em` +
 * `.mmm_quality` (and `build_mmm`'s information criteria). This is the
 * canonical tnaj home of `MMMResult`; `tnaw` provides a WASM-accelerated
 * implementation with the *same* result shape, and `tnajw` dispatches
 * between them. The Rust kernel (`WASMengine/rust/src/kernels/mmm.rs`)
 * mirrors this file line-for-line — keep them in lock-step.
 *
 * **Different validation contract from the deterministic 1e-10-vs-R
 * analyses.** Mixture-cluster labels are identifiable only up to
 * permutation and EM converges to a *local* optimum, so equivalence is
 * "ARI=1 + loglik", never element-wise on raw cluster ids. The "basic
 * deterministic" qualifier — fixed seed, single start, no random restarts
 * — is what makes a *given* fit bit-reproducible run-to-run. Reference is
 * `Nestimate:::.mmm_em` (a deterministic R MMM with injectable init), NOT
 * stochastic `seqHMM`.
 *
 * Why it exists alongside `clusterData`: distance-based clustering needs a
 * dense O(n²) distance matrix; MMM is O(N·K), linear in N, so it clusters
 * 100k+ sequences where the O(n²) path is infeasible.
 *
 * ## Parity decisions (must match the Rust kernel — see its header)
 *
 * 1. **Counts == `Nestimate:::.precompute_per_sequence_wide`
 *    (`method="relative"`).** Per sequence, count *consecutive position
 *    pairs* `(x[t], x[t+1])` and increment `(from,to)` **only if both
 *    endpoints are non-NA**. This is deliberately NOT NA-compaction
 *    (`A,NA,B → A,B`); Nestimate breaks the pair (`A,NA,B → ∅`). Raw
 *    integer counts. Pair index `from*S + to` (0-based) ==
 *    `(from-1)*n_states + to` in R.
 * 2. **Initial state == `match(raw_data[i, col1], states)`** — the *first
 *    position only*, no scan-forward. NA there is "uninformative": it
 *    contributes 0 to the M-step initial-count, but the E-step adds the
 *    state-0 row of `log_init` (R's `init_state_safe = 1`).
 * 3. **EM mirrors `.mmm_em`**: log-space E-step, log-sum-exp, log-zero
 *    epsilon `1e-300` (== R's deparsed `9.99999999999999e-301`).
 * 4. **Single start.** Optional caller `initPosterior` (N×K row-major)
 *    consumed verbatim (the R-cross-check hook); else a seeded
 *    `SeededRNG` draw `post[i][m]=rng.random()` row-normalized.
 * 5. **Hard assignment = argmax_m post, lowest index wins ties**
 *    (R `max.col(ties.method="first")`).
 */
import { Matrix } from '../core/matrix.js';
import { SeededRNG } from '../core/rng.js';
import { fitMultinom, multinomSE, type MultinomFit } from './multinom.js';
import type { SequenceData, TNA, GroupTNA } from '../core/types.js';
import { createTNA } from '../core/model.js';

/** log-zero guard — R `log(x + 9.99999999999999e-301)`. `1e-300` is the
 *  identical f64 bit pattern, so per-iteration arithmetic matches R. */
const EPS = 1e-300;

export interface MmmOptions {
  /** Number of mixture components K (≥2). Required. */
  k: number;
  /** Max EM iterations. Default 200 (R `build_mmm`). */
  maxIter?: number;
  /** Convergence tolerance on |Δloglik|. Default 1e-8. */
  tol?: number;
  /** Laplace smoothing (R `smooth`). Default 0.01 (R `build_mmm`). */
  alpha?: number;
  /** Seed for the deterministic init. Default 42. Ignored when
   *  `initPosterior` is supplied. */
  seed?: number;
  /**
   * COVARIATES on cluster membership — n x p, WITHOUT an intercept column (one is added).
   *
   * With these, the mixing weights stop being a single vector and become a multinomial logit
   * on the case: pi_i = softmax([1, X_i] · B). Membership is then MODELLED rather than
   * described after the fact, which is the whole point — the post-hoc route (cluster, then
   * ANOVA the covariates against the hard labels) discards classification uncertainty and
   * reports p-values that are too confident.
   */
  covariates?: number[][];
  /** Column names for `covariates`, length p. Reported with the coefficients. */
  covariateNames?: string[];
  /** The reference cluster, 1-indexed (its coefficients are fixed at 0). Default 1. */
  refCluster?: number;
  /** Number of independent EM starts (default 1). EM finds a *local*
   *  optimum, so on multimodal data more starts can find a better one.
   *  Uses the deterministic seed sequence `seed, seed+1, …,
   *  seed+nStarts-1` and returns the highest-logLik fit (ties → lowest
   *  seed), so the *whole* multi-start result stays reproducible.
   *  Inspect {@link MMMResult.restartLogLiks} to see whether the extra
   *  starts actually found anything. Forced to 1 when `initPosterior`
   *  is supplied (an explicit init is a single explicit start). */
  nStarts?: number;
  /** Optional N×K row-major starting responsibilities, consumed verbatim
   *  (the R-cross-check hook: feed both engines the same init so a
   *  0-restart EM lands in the same basin). */
  initPosterior?: Float64Array | number[];
}

/** Cluster-quality block — port of Nestimate `.mmm_quality`. */
export interface MmmQuality {
  /** Average Posterior Probability per cluster (length k). `NaN` for an
   *  empty hard-assignment cluster (R `NA_real_`). */
  avepp: Float64Array;
  /** Overall AvePP — mean over sequences of the max posterior. */
  aveppOverall: number;
  /** Normalized entropy ∈ [0,1]: 0 = perfect separation, 1 = random. */
  entropy: number;
  /** 1 − entropy. */
  relativeEntropy: number;
  /** Fraction of sequences whose max posterior < 0.5. */
  classificationError: number;
  /** ICL classification entropy: −Σ log(posterior[i, assignment_i] + ε). */
  classEntropy: number;
}

/** Canonical Mixture-Markov-Model result. `transition[m]` is a
 *  row-stochastic S×S `Matrix` for cluster m (row = "from", col = "to"). */
export interface MMMResult {
  k: number;
  /** 1-indexed hard assignment per sequence (ties → lowest index). */
  assignments: number[];
  /** Posterior responsibilities, n rows × k. */
  responsibilities: number[][];
  /** Mixing weights, length k. */
  pi: Float64Array;
  /** Initial-state distribution per cluster (k arrays, each length S). */
  delta: Float64Array[];
  /** Transition matrix per cluster (k × S×S, row-stochastic). */
  transition: Matrix[];
  logLik: number;
  /** Free parameters: k·S·(S−1) transitions + k·(S−1) initials + the mixing block —
   *  (k−1) without covariates, (k−1)·(p+1) with them. Reported rather than left implicit in
   *  AIC/BIC, because a fit report that shows AIC without saying what it penalised is asking
   *  the reader to take the penalty on trust. */
  df: number;
  aic: number;
  bic: number;
  /** Integrated Completed Likelihood = BIC + 2·classEntropy. */
  icl: number;
  /** Cluster-quality metrics (Nestimate `.mmm_quality`). */
  quality: MmmQuality;
  iterations: number;
  converged: boolean;
  /** EM starts performed (1 if `initPosterior` was supplied, else
   *  `nStarts`). The returned fit is the best of these. */
  nStarts: number;
  /** Per-restart converged logLik, in seed order (`seed..seed+nStarts`).
   *  `Math.max(...restartLogLiks) === logLik`. If every entry is the
   *  same value, the extra starts found nothing — one start sufficed and
   *  you can prove it; a wide spread means restarts mattered. */
  restartLogLiks: Float64Array;
  /** State vocabulary (sorted unique non-NA tokens — R `build_mmm`). */
  labels: string[];
  /** Number of input sequences (== assignments.length). */
  nSequences: number;
  /** Covariate model on cluster membership — present only when `covariates` was supplied. */
  covariateModel?: CovariateModel;
}

/** The multinomial logit on cluster membership: who ends up where, and how sure we are. */
export interface CovariateModel {
  /** ['(Intercept)', ...covariateNames] */
  terms: string[];
  /** The reference cluster, 1-indexed. Its coefficients are 0 by definition. */
  refCluster: number;
  /** The non-reference clusters, 1-indexed, in coefficient-row order. */
  clusters: number[];
  /** coefficients[m][j] — log-odds of cluster `clusters[m]` vs the reference, per unit of term j. */
  coefficients: number[][];
  /** exp(coefficients) — the odds-ratio reading. */
  oddsRatios: number[][];
  /** Standard errors by LOUIS' identity (observed = complete - missing information), so
   *  classification uncertainty is IN them. See multinom.ts. NaN where the information
   *  matrix is not invertible (a covariate that separates the clusters perfectly). */
  se: number[][];
  /** Wald z = coefficient / se, and its two-sided p. */
  z: number[][];
  pValues: number[][];
  /** Per-sequence prior cluster probabilities softmax([1,X_i]·B), n x k. */
  priors: number[][];
  /** False when the information matrix could not be inverted — SEs are NaN and the
   *  coefficients should be read as "separation", not as estimates. */
  seOk: boolean;
}

export type MmmInput = string[][] | SequenceData | TNA;

function isTNA(x: MmmInput): x is TNA {
  return !Array.isArray(x) && typeof x === 'object' && 'labels' in x && 'weights' in x;
}

/** Sorted unique non-NA tokens. Matches R `build_mmm`:
 *  `states <- sort(unique(as.vector(mat))); states[!is.na(states)]`.
 *  Unlike `clusterData`, NO sentinel→NA conversion (R `build_mmm` treats
 *  "*"/"%" as real states — recode to null *before* calling for padded
 *  data). */
function deriveLabels(rows: readonly (readonly (string | null | undefined)[])[]): string[] {
  const set = new Set<string>();
  for (const row of rows) {
    for (const v of row) {
      if (v === null || v === undefined || v === '') continue;
      set.add(v);
    }
  }
  return [...set].sort();
}

/**
 * Fit a Mixture Markov Model by single-start deterministic EM.
 *
 * @param data Sequence rows (wide format — positions are NOT compacted; an
 *   interior NA breaks a transition pair, matching R), or a `TNA` with
 *   `.data` (its `.labels` are reused as the state set, like R
 *   `build_mmm` on a tna object).
 * @param options See {@link MmmOptions}. `k` is required.
 */
/**
 * Validate resolved MMM hyper-parameters, mirroring R `build_mmm`'s
 * `stopifnot` block (finite/positive/whole guards) so invalid input fails
 * loud at the API boundary instead of silently degrading (e.g. `tol<=0`
 * never converges; `maxIter<1` yields a −Inf "fit"; `alpha<0` takes the
 * log of a negative). Exported so tnaj and tnaw enforce the *same*
 * contract — `tnajw` may dispatch to either, so the errors must match.
 */
export function validateMmmOptions(o: {
  k: number;
  maxIter: number;
  tol: number;
  alpha: number;
  seed: number;
  nStarts: number;
}): void {
  const whole = (x: number) => Number.isFinite(x) && Number.isInteger(x);
  if (!whole(o.k) || o.k < 2) {
    throw new Error('mmm: k must be a whole finite number >= 2');
  }
  if (!whole(o.maxIter) || o.maxIter < 1) {
    throw new Error('mmm: maxIter must be a positive whole finite number');
  }
  if (!Number.isFinite(o.tol) || o.tol <= 0) {
    throw new Error('mmm: tol must be a finite positive number');
  }
  if (!Number.isFinite(o.alpha) || o.alpha < 0) {
    throw new Error('mmm: alpha (Laplace smoothing) must be a finite non-negative number');
  }
  if (!whole(o.nStarts) || o.nStarts < 1) {
    throw new Error('mmm: nStarts must be a positive whole finite number');
  }
  if (!whole(o.seed) || o.seed < 0) {
    throw new Error('mmm: seed must be a non-negative whole finite number');
  }
}

export function mmm(data: MmmInput, options: MmmOptions): MMMResult {
  const { k } = options;
  const maxIter = options.maxIter ?? 200;
  const tol = options.tol ?? 1e-8;
  const alpha = options.alpha ?? 0.01;
  const seed = options.seed ?? 42;
  const nStartsOpt = options.nStarts ?? 1;
  validateMmmOptions({ k, maxIter, tol, alpha, seed, nStarts: nStartsOpt });

  let rows: readonly (readonly (string | null | undefined)[])[];
  let labels: string[];
  if (isTNA(data)) {
    if (!data.data) throw new Error('mmm: TNA model missing data');
    rows = data.data as SequenceData;
    labels = data.labels.slice();
  } else {
    rows = data as readonly (readonly (string | null)[])[];
    labels = deriveLabels(rows);
  }
  if (labels.length < 2) throw new Error('mmm: need at least 2 states');
  const n = rows.length;
  if (k > n) throw new Error(`mmm: k=${k} exceeds number of sequences (${n})`);

  const s = labels.length;
  const s2 = s * s;
  const labelIdx = new Map<string, number>();
  for (let i = 0; i < s; i++) labelIdx.set(labels[i]!, i);

  // ---- Per-sequence dense counts (N×S²) + initial state ----
  // counts[i*s2 + from*s + to]; initState[i] = state0 | -1 (NA).
  const counts = new Float64Array(n * s2);
  const initState = new Int32Array(n);
  for (let i = 0; i < n; i++) {
    const row = rows[i]!;
    const first = row.length > 0 ? row[0] : null;
    const fi = first == null || first === '' ? undefined : labelIdx.get(first);
    initState[i] = fi === undefined ? -1 : fi;
    const base = i * s2;
    for (let t = 0; t + 1 < row.length; t++) {
      const a = row[t];
      const b = row[t + 1];
      if (a == null || a === '' || b == null || b === '') continue;
      const fa = labelIdx.get(a);
      const fb = labelIdx.get(b);
      if (fa === undefined || fb === undefined) continue;
      counts[base + fa * s + fb] = counts[base + fa * s + fb]! + 1;
    }
  }

  // ---- One EM run to convergence from a given initial `post0` ----
  // Pure recurrence (no RNG): every restart and the Rust kernel's
  // `run_em` share this exact loop — that lock-step is what keeps
  // WASM≡TS and the R cross-check valid.
  // ---- Covariate design matrix: [1, X_i]. Built once; `null` = plain MMM. ----
  const covRaw = options.covariates;
  let design: number[][] | null = null;
  let refIdx = 0;
  if (covRaw) {
    if (covRaw.length !== n) {
      throw new Error(`mmm: covariates must have one row per sequence (got ${covRaw.length}, need ${n})`);
    }
    const p = covRaw[0]?.length ?? 0;
    design = covRaw.map((r, i) => {
      if (r.length !== p) throw new Error(`mmm: covariate row ${i} has ${r.length} columns, expected ${p}`);
      // A non-finite covariate would poison the softmax and surface as a silent NaN
      // likelihood twenty iterations later, so it is refused here where it can be named.
      for (const v of r) if (!Number.isFinite(v)) throw new Error(`mmm: covariate row ${i} contains a non-finite value`);
      return [1, ...r];
    });
    const rc = options.refCluster ?? 1;
    if (!Number.isInteger(rc) || rc < 1 || rc > k) throw new Error(`mmm: refCluster must be in 1..${k}`);
    refIdx = rc - 1;
  }

  interface EmFit {
    post: Float64Array;
    pAll: Float64Array;
    initAll: Float64Array;
    pi: Float64Array;
    ll: number;
    iterations: number;
    converged: boolean;
    /** Present only with covariates: the fitted multinomial logit on membership. */
    mn: MultinomFit | null;
  }
  function runEm(post0: Float64Array): EmFit {
    const post = post0; // consumed/overwritten in place
    const pAll = new Float64Array(s2 * k); // [pair0*k + m], pair0 = from*s+to
    const initAll = new Float64Array(s * k); // [state*k + m]
    const pi = new Float64Array(k);
    const logLikRow = new Float64Array(n * k);
    // With covariates the prior is per SEQUENCE, not one vector — logPriors[i*k + m].
    const logPriors = new Float64Array(n * k);
    let mn: MultinomFit | null = null;
    let ll = -Infinity;
    let llPrev = -Infinity;
    let converged = false;
    let iterations = 0;

    for (let iter = 1; iter <= maxIter; iter++) {
      iterations = iter;

      // M-step: P_unnorm = countsᵀ·post + smooth
      pAll.fill(alpha);
      for (let i = 0; i < n; i++) {
        const cb = i * s2;
        const pb = i * k;
        for (let pair0 = 0; pair0 < s2; pair0++) {
          const c = counts[cb + pair0]!;
          if (c !== 0) {
            const base = pair0 * k;
            for (let m = 0; m < k; m++) pAll[base + m] = pAll[base + m]! + c * post[pb + m]!;
          }
        }
      }
      // Row-stochastic over `to`: per (from, cluster) normalize.
      for (let from = 0; from < s; from++) {
        for (let m = 0; m < k; m++) {
          let fsum = 0;
          for (let to = 0; to < s; to++) fsum += pAll[(from * s + to) * k + m]!;
          if (fsum === 0) fsum = 1;
          for (let to = 0; to < s; to++) {
            pAll[(from * s + to) * k + m] = pAll[(from * s + to) * k + m]! / fsum;
          }
        }
      }

      // init_unnorm = init_indᵀ·post + smooth, column-normalized per cluster.
      initAll.fill(alpha);
      for (let i = 0; i < n; i++) {
        const st = initState[i]!;
        if (st >= 0) {
          const pb = i * k;
          const ib = st * k;
          for (let m = 0; m < k; m++) initAll[ib + m] = initAll[ib + m]! + post[pb + m]!;
        }
      }
      for (let m = 0; m < k; m++) {
        let isum = 0;
        for (let st = 0; st < s; st++) isum += initAll[st * k + m]!;
        if (isum === 0) isum = 1;
        for (let st = 0; st < s; st++) initAll[st * k + m] = initAll[st * k + m]! / isum;
      }

      // ---- M-step for the MIXING WEIGHTS ----
      // Without covariates: pi_m = mean_i post[i,m], a single vector.
      // With them: a weighted multinomial logit of the RESPONSIBILITIES on the covariates —
      // pi_i = softmax([1,X_i]·B). The responses are the soft posteriors, never hard labels,
      // which is precisely what keeps classification uncertainty inside the estimate instead
      // of being thrown away by a post-hoc test on the assignments.
      for (let m = 0; m < k; m++) {
        let acc = 0;
        for (let i = 0; i < n; i++) acc += post[i * k + m]!;
        pi[m] = acc / n;                        // still reported: the AVERAGE mixing weight
      }
      if (design) {
        const R: number[][] = new Array(n);
        for (let i = 0; i < n; i++) {
          const r = new Array<number>(k);
          for (let m = 0; m < k; m++) r[m] = post[i * k + m]!;
          R[i] = r;
        }
        // Warm-started from the previous M-step: inside EM the coefficients barely move
        // between iterations, so this costs a couple of Newton steps, not a fresh fit.
        mn = fitMultinom(design, R, refIdx, mn ? mn.beta : undefined);
        for (let i = 0; i < n; i++) {
          for (let m = 0; m < k; m++) logPriors[i * k + m] = Math.log(mn.priors[i]![m]! + EPS);
        }
      } else {
        for (let i = 0; i < n; i++) {
          for (let m = 0; m < k; m++) logPriors[i * k + m] = Math.log(pi[m]! + EPS);
        }
      }

      // E-step
      for (let i = 0; i < n; i++) {
        const cb = i * s2;
        const lb = i * k;
        const st = initState[i]! < 0 ? 0 : initState[i]!; // NA → state 0
        for (let m = 0; m < k; m++) {
          let acc = 0;
          for (let pair0 = 0; pair0 < s2; pair0++) {
            const c = counts[cb + pair0]!;
            if (c !== 0) acc += c * Math.log(pAll[pair0 * k + m]! + EPS);
          }
          acc += Math.log(initAll[st * k + m]! + EPS);
          acc += logPriors[lb + m]!;   // per-sequence prior when covariates are in play
          logLikRow[lb + m] = acc;
        }
      }

      // log-sum-exp → posterior + total loglik
      ll = 0;
      for (let i = 0; i < n; i++) {
        const lb = i * k;
        let logMax = -Infinity;
        for (let m = 0; m < k; m++) {
          const v = logLikRow[lb + m]!;
          if (v > logMax) logMax = v;
        }
        let rowSum = 0;
        for (let m = 0; m < k; m++) {
          const e = Math.exp(logLikRow[lb + m]! - logMax);
          post[lb + m] = e;
          rowSum += e;
        }
        if (rowSum === 0) rowSum = EPS;
        for (let m = 0; m < k; m++) post[lb + m] = post[lb + m]! / rowSum;
        ll += logMax + Math.log(rowSum);
      }

      if (Math.abs(ll - llPrev) < tol) {
        converged = true;
        break;
      }
      llPrev = ll;
    }
    return { post, pAll, initAll, pi, ll, iterations, converged, mn };
  }

  // ---- Multi-start driver ----
  // External init ⇒ a single explicit start (the cross-check contract).
  let nStarts = Math.max(1, Math.floor(options.nStarts ?? 1));
  const explicitInit = options.initPosterior != null;
  if (explicitInit) {
    const ip = options.initPosterior!;
    if (ip.length !== n * k) {
      throw new Error(`mmm: initPosterior must have length n*k (${n * k})`);
    }
    nStarts = 1;
  }
  const restartLogLiks = new Float64Array(nStarts);
  let best: EmFit | null = null;
  for (let r = 0; r < nStarts; r++) {
    const post0 = new Float64Array(n * k);
    if (explicitInit) {
      const ip = options.initPosterior!;
      for (let idx = 0; idx < n * k; idx++) post0[idx] = ip[idx]!;
    } else {
      // Deterministic seed sequence: seed, seed+1, …  (xoshiro is the
      // same algorithm the Rust kernel uses, so the WASM and TS paths
      // draw the identical init for a given seed).
      const rng = new SeededRNG((seed + r) >>> 0);
      for (let i = 0; i < n; i++) {
        let rsum = 0;
        for (let m = 0; m < k; m++) {
          const v = rng.random();
          post0[i * k + m] = v;
          rsum += v;
        }
        if (rsum === 0) rsum = 1;
        for (let m = 0; m < k; m++) post0[i * k + m] = post0[i * k + m]! / rsum;
      }
    }
    const fit = runEm(post0);
    restartLogLiks[r] = fit.ll;
    // Strictly-greater ⇒ earliest (lowest-seed) optimum wins ties, so the
    // whole multi-start result is itself deterministic.
    if (best === null || fit.ll > best.ll) best = fit;
  }
  const { post, pAll, initAll, pi, ll, iterations, converged } = best!;

  // ---- Hard assignment (argmax, ties → lowest index) ----
  const assignments = new Array<number>(n);
  for (let i = 0; i < n; i++) {
    const lb = i * k;
    let best = 0;
    let bestV = post[lb]!;
    for (let m = 1; m < k; m++) {
      if (post[lb + m]! > bestV) {
        bestV = post[lb + m]!;
        best = m;
      }
    }
    assignments[i] = best + 1;
  }

  // ---- Quality (port of `.mmm_quality`) ----
  const avepp = new Float64Array(k).fill(NaN);
  {
    const sumM = new Float64Array(k);
    const cntM = new Int32Array(k);
    for (let i = 0; i < n; i++) {
      const m = assignments[i]! - 1;
      sumM[m] = sumM[m]! + post[i * k + m]!;
      cntM[m] = cntM[m]! + 1;
    }
    for (let m = 0; m < k; m++) if (cntM[m]! > 0) avepp[m] = sumM[m]! / cntM[m]!;
  }
  let aveppOverall = 0;
  let classificationError = 0;
  let classEntropy = 0;
  let entRaw = 0;
  for (let i = 0; i < n; i++) {
    const lb = i * k;
    let mx = post[lb]!;
    for (let m = 1; m < k; m++) if (post[lb + m]! > mx) mx = post[lb + m]!;
    aveppOverall += mx;
    if (mx < 0.5) classificationError += 1;
    classEntropy -= Math.log(post[lb + (assignments[i]! - 1)]! + EPS);
    for (let m = 0; m < k; m++) {
      const v = post[lb + m]!;
      entRaw -= v * Math.log(v + EPS);
    }
  }
  aveppOverall /= n;
  classificationError /= n;
  const entMax = n * Math.log(k);
  const entropy = entMax > 0 ? entRaw / entMax : 0;
  const relativeEntropy = 1 - entropy;

  // ---- Information criteria ----
  // The mixing weights cost (k-1) free parameters WITHOUT covariates — and (k-1)*(p+1) WITH
  // them, one intercept plus one slope per covariate for every non-reference cluster. Leaving
  // df at (k-1) would let every added covariate improve the likelihood for free, so BIC would
  // reward complexity and the model-selection table would be quietly, systematically wrong.
  const nMixParams = design ? (k - 1) * design[0]!.length : (k - 1);
  const nParams = k * s * (s - 1) + k * (s - 1) + nMixParams;
  const bic = -2 * ll + nParams * Math.log(n);
  const aic = -2 * ll + 2 * nParams;
  const icl = bic + 2 * classEntropy;

  // ---- Repack outputs ----
  const responsibilities: number[][] = new Array(n);
  for (let i = 0; i < n; i++) {
    const r = new Array<number>(k);
    for (let m = 0; m < k; m++) r[m] = post[i * k + m]!;
    responsibilities[i] = r;
  }
  const delta: Float64Array[] = new Array(k);
  const transition: Matrix[] = new Array(k);
  for (let m = 0; m < k; m++) {
    const d = new Float64Array(s);
    for (let st = 0; st < s; st++) d[st] = initAll[st * k + m]!;
    delta[m] = d;
    const M = Matrix.zeros(s, s);
    for (let from = 0; from < s; from++) {
      for (let to = 0; to < s; to++) M.set(from, to, pAll[(from * s + to) * k + m]!);
    }
    transition[m] = M;
  }

  return {
    k,
    assignments,
    responsibilities,
    pi,
    delta,
    transition,
    logLik: ll,
    df: nParams,
    aic,
    bic,
    icl,
    quality: {
      avepp,
      aveppOverall,
      entropy,
      relativeEntropy,
      classificationError,
      classEntropy,
    },
    iterations,
    converged,
    nStarts,
    restartLogLiks,
    labels,
    nSequences: n,
    covariateModel: buildCovariateModel(),
  };

  /** The membership logit, packaged for reporting. Undefined for a plain MMM. */
  function buildCovariateModel(): CovariateModel | undefined {
    if (!design || !best || !best.mn) return undefined;
    const mnFit = best.mn;
    const p1 = design[0]!.length;
    const names = options.covariateNames && options.covariateNames.length === p1 - 1
      ? options.covariateNames.slice()
      : Array.from({ length: p1 - 1 }, (_, j) => 'X' + (j + 1));
    const terms = ['(Intercept)', ...names];

    const R: number[][] = new Array(n);
    for (let i = 0; i < n; i++) {
      const r = new Array<number>(k);
      for (let m = 0; m < k; m++) r[m] = best!.post[i * k + m]!;
      R[i] = r;
    }
    const { se, ok } = multinomSE(design, R, mnFit.priors, refIdx);

    const clusters: number[] = [];
    for (let c = 0; c < k; c++) if (c !== refIdx) clusters.push(c + 1);

    const z = mnFit.beta.map((row, m) => row.map((b, j) => b / se[m]![j]!));
    const pValues = z.map((row) => row.map((v) => (Number.isFinite(v) ? 2 * (1 - normalCdf(Math.abs(v))) : NaN)));

    return {
      terms,
      refCluster: refIdx + 1,
      clusters,
      coefficients: mnFit.beta.map((r) => r.slice()),
      oddsRatios: mnFit.beta.map((r) => r.map((b) => Math.exp(b))),
      se,
      z,
      pValues,
      priors: mnFit.priors.map((r) => r.slice()),
      seOk: ok,
    };
  }
}

/** Standard normal CDF (Abramowitz & Stegun 7.1.26 via erf) — for the Wald p-values. */
function normalCdf(x: number): number {
  const t = 1 / (1 + 0.2316419 * Math.abs(x));
  const d = 0.3989422804014327 * Math.exp(-x * x / 2);
  const pr = d * t * (0.319381530 + t * (-0.356563782 + t * (1.781477937 + t * (-1.821255978 + t * 1.330274429))));
  return x > 0 ? 1 - pr : pr;
}

// ---------------------------------------------------------------------------
// clusterMmm — GroupTNA wrapper (parallel to R Nestimate::cluster_mmm)
// ---------------------------------------------------------------------------

/** MMM clustering metadata carried on the `GroupTNA` returned by
 *  {@link clusterMmm}. Mirrors R `net_mmm_clustering`: everything the
 *  {@link MMMResult} has except the per-cluster networks (those are the
 *  `models`). Lets downstream tnaj group tooling recover the soft
 *  assignment, fit, and quality without re-running EM. */
export interface MmmClustering {
  k: number;
  /** 1-indexed hard assignment per sequence (ties → lowest index). */
  assignments: number[];
  /** Posterior responsibilities, n rows × k. */
  responsibilities: number[][];
  /** Mixing weights, length k. */
  mixing: Float64Array;
  /** Cluster-quality metrics (Nestimate `.mmm_quality`). */
  quality: MmmQuality;
  logLik: number;
  /** Free parameters (see MMMResult.df). */
  df: number;
  aic: number;
  bic: number;
  icl: number;
  iterations: number;
  converged: boolean;
  nStarts: number;
  /** The membership logit, when covariates were supplied. Carried through clusterMmm so a
   *  caller that clusters through the GroupTNA wrapper can still report WHO ends up where —
   *  otherwise the whole point of fitting with covariates is lost at the wrapper boundary. */
  covariateModel?: CovariateModel;
  restartLogLiks: Float64Array;
  labels: string[];
  nSequences: number;
  /** The full N-row sequence frame used for estimation, aligned to
   *  `assignments` (so a caller can recover both for sequence plots). */
  data: SequenceData;
}

/** A {@link GroupTNA} (one TNA per mixture component) plus the MMM
 *  clustering metadata. The extra `clustering` field is additive — the
 *  object is still a structurally valid `GroupTNA`, so it flows through
 *  every tnaj group consumer (group plots, `compareModels`, etc.). */
export interface MmmGroupTNA extends GroupTNA {
  clustering: MmmClustering;
}

/**
 * Cluster sequences with a Mixture Markov Model and return a
 * {@link GroupTNA} — one TNA per component, the EM-estimated transition
 * matrix as its `weights` and the EM initial distribution as its `inits`,
 * carrying the rows assigned to that component in `data`. This is the
 * model-based counterpart to distance-based `clusterData`, and the tnaj
 * analogue of R `Nestimate::cluster_mmm` (which returns a
 * `netobject_group` + `attr(,"clustering")`).
 *
 * For the raw fit (responsibilities, ICs, quality) without the per-cluster
 * networks, call {@link mmm} directly — this wraps it and additionally
 * exposes the same numbers on `.clustering`.
 *
 * @example
 * const grp = clusterMmm(seqs, { k: 3 });
 * grp.models['Cluster 1'].weights;        // component-1 transition TNA
 * grp.clustering.assignments;             // hard labels (1..k)
 * grp.clustering.quality.aveppOverall;    // fit quality
 */
export function clusterMmm(data: MmmInput, options: MmmOptions): MmmGroupTNA {
  const fit = mmm(data, options);

  // Re-derive the N-row frame exactly as `mmm` did, so subsetting by
  // `assignments` (which is in input order) lines up row-for-row.
  let rows: SequenceData;
  if (isTNA(data)) {
    rows = (data.data ?? []) as SequenceData;
  } else {
    rows = (data as SequenceData).map((r) => r.slice());
  }

  const models: Record<string, TNA> = {};
  for (let m = 0; m < fit.k; m++) {
    const memberRows: SequenceData = [];
    for (let i = 0; i < fit.assignments.length; i++) {
      if (fit.assignments[i] === m + 1) memberRows.push(rows[i] ?? []);
    }
    // weights = EM component transition matrix; inits = EM initial dist.
    // Type 'relative' (row-stochastic) — matches the estimator and lets
    // plot_tna / compareModels treat it like any other relative TNA.
    models[`Cluster ${m + 1}`] = createTNA(
      fit.transition[m]!,
      fit.delta[m]!,
      fit.labels.slice(),
      memberRows,
      'relative',
      [],
    );
  }

  const clustering: MmmClustering = {
    k: fit.k,
    assignments: fit.assignments,
    responsibilities: fit.responsibilities,
    mixing: fit.pi,
    quality: fit.quality,
    logLik: fit.logLik,
    df: fit.df,
    aic: fit.aic,
    bic: fit.bic,
    icl: fit.icl,
    iterations: fit.iterations,
    converged: fit.converged,
    covariateModel: fit.covariateModel,
    nStarts: fit.nStarts,
    restartLogLiks: fit.restartLogLiks,
    labels: fit.labels,
    nSequences: fit.nSequences,
    data: rows,
  };

  return { models, clustering };
}

// ── Posterior assignment of (possibly held-out) sequences ────────────────────
//
// The EM's memory is O(n·S²): at 1.67 M sequences × 14 states that is a 2.4 GB
// count block no browser tab can hold. But once a mixture is FITTED — on a
// sample — every sequence can be scored against the k components in a single
// linear pass: log π_m + log δ_m[s₀] + Σ log P_m[from,to]. Same math as the
// E-step (EPS smoothing, NA initial state falls back to state 0, unknown/NA
// tokens skip the pair), so a sequence that WAS in the fitting sample gets its
// EM assignment back (modulo the vanishing difference between the final M-step
// parameters and the last E-step posterior).

export interface MmmAssignParams {
  /** Mixing weights (MMMResult.pi / MmmClustering.mixing). */
  pi: ArrayLike<number>;
  /** Initial-state distribution per cluster (MMMResult.delta). */
  delta: ArrayLike<number>[];
  /** Row-stochastic S×S transition matrix per cluster (MMMResult.transition). */
  transition: Matrix[];
  /** State vocabulary the mixture was fitted on (MMMResult.labels). */
  labels: string[];
}

export interface MmmAssignResult {
  /** 1-indexed hard assignment per sequence (ties → lowest index). */
  assignments: number[];
  /** Max posterior per sequence (softmax over the k component log-scores). */
  avepp: Float64Array;
  /** Mean of `avepp`. */
  aveppOverall: number;
  /** Per-cluster sequence counts, length k. */
  counts: number[];
  nSequences: number;
}

/**
 * Assign every sequence to its maximum-posterior mixture component.
 *
 * @param data  Sequences (same shapes `mmm`/`clusterMmm` accept).
 * @param params  Fitted mixture parameters — pass the fields straight off an
 *   `MMMResult`, or reassemble from a `clusterMmm` result (`clustering.mixing`,
 *   the models' `inits`/`weights`, `clustering.labels`).
 */
export function mmmAssign(data: MmmInput, params: MmmAssignParams): MmmAssignResult {
  const rows: SequenceData = isTNA(data)
    ? ((data.data ?? []) as SequenceData)
    : (data as SequenceData);
  const { labels, transition } = params;
  const k = transition.length;
  const s = labels.length;
  if (k < 1) throw new Error('mmmAssign: need at least 1 component');
  if (params.delta.length !== k) throw new Error(`mmmAssign: delta has ${params.delta.length} entries, expected k=${k}`);
  if ((params.pi as { length: number }).length !== k) throw new Error(`mmmAssign: pi has ${(params.pi as { length: number }).length} entries, expected k=${k}`);
  const labelIdx = new Map<string, number>();
  for (let i = 0; i < s; i++) labelIdx.set(labels[i]!, i);

  // Pre-log everything once — the scan is then pure adds.
  const logPi = new Float64Array(k);
  const logDelta = new Float64Array(k * s);
  const logP = new Float64Array(k * s * s);
  for (let m = 0; m < k; m++) {
    logPi[m] = Math.log((params.pi[m] ?? 0) + EPS);
    const dm = params.delta[m]!;
    if ((dm as { length: number }).length !== s) throw new Error(`mmmAssign: delta[${m}] has ${(dm as { length: number }).length} states, expected ${s}`);
    const tm = transition[m]!;
    if (tm.rows !== s || tm.cols !== s) throw new Error(`mmmAssign: transition[${m}] is ${tm.rows}×${tm.cols}, expected ${s}×${s}`);
    for (let st = 0; st < s; st++) logDelta[m * s + st] = Math.log((dm[st] ?? 0) + EPS);
    for (let a = 0; a < s; a++) {
      for (let b = 0; b < s; b++) logP[(m * s + a) * s + b] = Math.log(tm.get(a, b) + EPS);
    }
  }

  const n = rows.length;
  const assignments = new Array<number>(n);
  const avepp = new Float64Array(n);
  const counts = new Array<number>(k).fill(0);
  const score = new Float64Array(k);
  let aveppSum = 0;

  for (let i = 0; i < n; i++) {
    const row = rows[i] ?? [];
    const first = row.length > 0 ? row[0] : null;
    const fi = first == null || first === '' ? undefined : labelIdx.get(first);
    const st0 = fi === undefined ? 0 : fi; // NA initial → state 0, as the E-step does
    for (let m = 0; m < k; m++) score[m] = logPi[m]! + logDelta[m * s + st0]!;
    for (let t = 0; t + 1 < row.length; t++) {
      const a = row[t];
      const b = row[t + 1];
      if (a == null || a === '' || b == null || b === '') continue;
      const fa = labelIdx.get(a);
      const fb = labelIdx.get(b);
      if (fa === undefined || fb === undefined) continue;
      for (let m = 0; m < k; m++) score[m] = score[m]! + logP[(m * s + fa) * s + fb]!;
    }
    // argmax (ties → lowest) + softmax max via logsumexp for the posterior.
    let best = 0;
    for (let m = 1; m < k; m++) if (score[m]! > score[best]!) best = m;
    let denom = 0;
    for (let m = 0; m < k; m++) denom += Math.exp(score[m]! - score[best]!);
    assignments[i] = best + 1;
    avepp[i] = 1 / denom;
    aveppSum += avepp[i]!;
    counts[best] = counts[best]! + 1;
  }

  return { assignments, avepp, aveppOverall: n ? aveppSum / n : NaN, counts, nSequences: n };
}
