/**
 * Weighted multinomial logistic regression — the M-step of a COVARIATE mixture model.
 *
 * A plain mixture Markov model has one mixing weight per cluster: pi_m, the same for every
 * sequence. A covariate MMM lets the mixing weights depend on what you know about the case:
 *
 *     pi_i = softmax(X_i · B)
 *
 * so "who ends up in cluster 2" becomes a multinomial logit on the metadata, estimated
 * INSIDE the EM rather than tested after it. That is the whole difference between modelling
 * membership and describing it: the post-hoc route (cluster, then ANOVA the covariates
 * against the hard labels) throws away classification uncertainty and reports p-values that
 * are too confident. Here the responsibilities stay soft and the covariates see them soft.
 *
 * The responses are therefore FRACTIONAL — R[i][m] is a posterior, not a 0/1 label — which
 * is exactly `nnet::multinom` with case weights, and is what the parity test pins against.
 *
 * Fitted by Newton–Raphson on the full (k-1)x(p+1) coefficient block:
 *     score:    g[m][j] = sum_i x_ij (R_im - pi_im)
 *     information: I[(m,j),(l,q)] = sum_i x_ij x_iq pi_im (delta_ml - pi_il)
 * Both are exact; there is no line search because the multinomial log-likelihood is concave
 * in B, so undamped Newton converges from any start.
 */

/** Row-major (k-1) x p1 coefficients, plus what the caller needs to report them. */
export interface MultinomFit {
  /** beta[m][j] — m indexes the NON-REFERENCE clusters in order, j the columns of X. */
  beta: number[][];
  /** Fitted priors, n x k, in ORIGINAL cluster order (the reference class included). */
  priors: number[][];
  /** Weighted multinomial log-likelihood at the fit. */
  logLik: number;
  iterations: number;
  converged: boolean;
}

/** Solve A·x = b in place by Gauss–Jordan with partial pivoting. Returns null if singular.
 *  Also used to invert the information matrix for standard errors. */
export function solveLinear(A: number[][], b: number[]): number[] | null {
  const n = b.length;
  const M = A.map((r, i) => r.concat([b[i]!]));
  for (let c = 0; c < n; c++) {
    let piv = c;
    for (let r = c + 1; r < n; r++) if (Math.abs(M[r]![c]!) > Math.abs(M[piv]![c]!)) piv = r;
    if (Math.abs(M[piv]![c]!) < 1e-12) return null;
    if (piv !== c) { const t = M[piv]!; M[piv] = M[c]!; M[c] = t; }
    const d = M[c]![c]!;
    for (let j = c; j <= n; j++) M[c]![j] = M[c]![j]! / d;
    for (let r = 0; r < n; r++) {
      if (r === c) continue;
      const f = M[r]![c]!;
      if (f === 0) continue;
      for (let j = c; j <= n; j++) M[r]![j] = M[r]![j]! - f * M[c]![j]!;
    }
  }
  return M.map((r) => r[n]!);
}

/** Inverse of a symmetric positive-definite matrix, or null if it is not invertible. */
export function invertMatrix(A: number[][]): number[][] | null {
  const n = A.length;
  const inv: number[][] = [];
  for (let c = 0; c < n; c++) {
    const e = new Array<number>(n).fill(0);
    e[c] = 1;
    const col = solveLinear(A, e);
    if (!col) return null;
    inv.push(col);
  }
  // solveLinear returned COLUMNS; transpose back.
  return Array.from({ length: n }, (_, i) => Array.from({ length: n }, (_, j) => inv[j]![i]!));
}

/** softmax over the k clusters given the (k-1) non-reference linear predictors. */
function priorsOf(eta: number[], refIdx: number, k: number): number[] {
  // eta is indexed by NON-reference position; the reference class has eta = 0 by definition
  // (that is what makes B identified at all — without it you could add any constant to every
  // cluster's predictor and change nothing).
  const full = new Array<number>(k);
  let maxE = 0;                       // reference class contributes eta = 0
  let e = 0;
  for (let c = 0; c < k; c++) {
    if (c === refIdx) { full[c] = 0; continue; }
    const v = eta[e++]!;
    full[c] = v;
    if (v > maxE) maxE = v;
  }
  let sum = 0;
  for (let c = 0; c < k; c++) { full[c] = Math.exp(full[c]! - maxE); sum += full[c]!; }
  for (let c = 0; c < k; c++) full[c] = full[c]! / sum;
  return full;
}

/**
 * Fit softmax(X·B) to fractional responses R by Newton–Raphson.
 *
 * @param X    n x p1 design matrix — INTERCEPT COLUMN INCLUDED by the caller.
 * @param R    n x k  responses. Rows need not be 0/1; they are posteriors and sum to 1.
 * @param refIdx  the reference cluster (its coefficients are fixed at 0).
 * @param beta0   warm start, (k-1) x p1. Inside EM this is the previous iteration's B, which
 *                is what makes the M-step cost a couple of Newton steps rather than a fit.
 * @param ridge   tiny diagonal added to the information matrix. Not regularisation for its
 *                own sake: with a covariate that perfectly separates the clusters the MLE
 *                runs off to infinity and the information matrix goes singular, and this
 *                keeps the solve defined so the EM can finish and REPORT the separation
 *                (a huge coefficient with a huge SE) instead of dying with a linear-algebra
 *                error the user cannot act on.
 */

/** log det of the expected information at B — the Jeffreys penalty's kernel. */
function logDetInfo(
  X: number[][], beta: number[][], refIdx: number, k: number,
  nonRef: number[], p1: number, ridge: number,
): number {
  const km1 = k - 1;
  const dim = km1 * p1;
  const I: number[][] = Array.from({ length: dim }, () => new Array<number>(dim).fill(0));
  for (let i = 0; i < X.length; i++) {
    const xi = X[i]!;
    const eta = new Array<number>(km1);
    for (let m = 0; m < km1; m++) {
      let acc = 0;
      for (let j = 0; j < p1; j++) acc += xi[j]! * beta[m]![j]!;
      eta[m] = acc;
    }
    const pr = priorsOf(eta, refIdx, k);
    for (let m = 0; m < km1; m++) {
      const pm = pr[nonRef[m]!]!;
      for (let l = 0; l < km1; l++) {
        const w = pm * ((m === l ? 1 : 0) - pr[nonRef[l]!]!);
        if (w === 0) continue;
        for (let j = 0; j < p1; j++) {
          const xw = xi[j]! * w;
          for (let q = 0; q < p1; q++) I[m * p1 + j]![l * p1 + q] = I[m * p1 + j]![l * p1 + q]! + xw * xi[q]!;
        }
      }
    }
  }
  for (let d = 0; d < dim; d++) I[d]![d] = I[d]![d]! + ridge;
  // log|det| by LU with partial pivoting.
  let logDet = 0;
  const M = I.map((r) => r.slice());
  for (let c = 0; c < dim; c++) {
    let piv = c;
    for (let r = c + 1; r < dim; r++) if (Math.abs(M[r]![c]!) > Math.abs(M[piv]![c]!)) piv = r;
    if (Math.abs(M[piv]![c]!) < 1e-300) return -Infinity;
    if (piv !== c) { const t = M[piv]!; M[piv] = M[c]!; M[c] = t; }
    logDet += Math.log(Math.abs(M[c]![c]!));
    for (let r = c + 1; r < dim; r++) {
      const f = M[r]![c]! / M[c]![c]!;
      for (let j = c; j < dim; j++) M[r]![j] = M[r]![j]! - f * M[c]![j]!;
    }
  }
  return logDet;
}

export function fitMultinom(
  X: number[][],
  R: number[][],
  refIdx: number,
  beta0?: number[][],
  opts?: { maxIter?: number; tol?: number; ridge?: number; firth?: boolean },
): MultinomFit {
  const n = X.length;
  const p1 = n > 0 ? X[0]!.length : 0;
  const k = n > 0 ? R[0]!.length : 0;
  const km1 = k - 1;
  const maxIter = opts?.maxIter ?? 100;
  const tol = opts?.tol ?? 1e-10;
  const ridge = opts?.ridge ?? 1e-9;

  // Non-reference clusters, in cluster order.
  const nonRef: number[] = [];
  for (let c = 0; c < k; c++) if (c !== refIdx) nonRef.push(c);

  const beta: number[][] = beta0
    ? beta0.map((r) => r.slice())
    : Array.from({ length: km1 }, () => new Array<number>(p1).fill(0));

  const dim = km1 * p1;
  const priors: number[][] = new Array(n);
  let logLik = -Infinity;
  let iterations = 0;
  let converged = false;

  for (let it = 1; it <= maxIter; it++) {
    iterations = it;

    // ---- priors + log-likelihood at the current B ----
    let ll = 0;
    for (let i = 0; i < n; i++) {
      const eta = new Array<number>(km1);
      for (let m = 0; m < km1; m++) {
        let acc = 0;
        for (let j = 0; j < p1; j++) acc += X[i]![j]! * beta[m]![j]!;
        eta[m] = acc;
      }
      const pr = priorsOf(eta, refIdx, k);
      priors[i] = pr;
      for (let c = 0; c < k; c++) {
        const r = R[i]![c]!;
        if (r > 0) ll += r * Math.log(Math.max(pr[c]!, 1e-300));
      }
    }

    // ---- score and information ----
    const g = new Array<number>(dim).fill(0);
    const I: number[][] = Array.from({ length: dim }, () => new Array<number>(dim).fill(0));
    for (let i = 0; i < n; i++) {
      const xi = X[i]!, pr = priors[i]!;
      for (let m = 0; m < km1; m++) {
        const cm = nonRef[m]!;
        const resid = R[i]![cm]! - pr[cm]!;
        for (let j = 0; j < p1; j++) g[m * p1 + j] = g[m * p1 + j]! + xi[j]! * resid;
      }
      for (let m = 0; m < km1; m++) {
        const pm = pr[nonRef[m]!]!;
        for (let l = 0; l < km1; l++) {
          const pl = pr[nonRef[l]!]!;
          const w = pm * ((m === l ? 1 : 0) - pl);
          if (w === 0) continue;
          for (let j = 0; j < p1; j++) {
            const xw = xi[j]! * w;
            for (let q = 0; q < p1; q++) {
              I[m * p1 + j]![l * p1 + q] = I[m * p1 + j]![l * p1 + q]! + xw * xi[q]!;
            }
          }
        }
      }
    }
    for (let d = 0; d < dim; d++) I[d]![d] = I[d]![d]! + ridge;

    // FIRTH / bias reduction. With complete separation the plain MLE runs to infinity: a
    // covariate that perfectly splits the clusters yields an unbounded coefficient, and the
    // "estimate" you print is really a statement about your iteration cap. Firth maximises the
    // JEFFREYS-PENALISED likelihood instead — l*(B) = l(B) + ½·log det I(B) — which keeps the
    // estimate finite and the direction honest. For a baseline-category logit this is exactly
    // what brglm2::brmultinom does by default (mean bias reduction ≡ Jeffreys penalty), which
    // is what Nestimate's `estimator = "auto"` switches to, and what this is pinned against.
    //
    // The penalty's gradient is taken by central differences on log det I. The parameter block
    // is small ((k−1)·p₁) and this is called a handful of times, so an analytic derivative
    // would buy nothing but a chance to get it wrong.
    if (opts?.firth) {
      const h = 1e-5;
      for (let d = 0; d < dim; d++) {
        const m = Math.floor(d / p1), j = d % p1;
        const b0 = beta[m]![j]!;
        beta[m]![j] = b0 + h;
        const up = logDetInfo(X, beta, refIdx, k, nonRef, p1, ridge);
        beta[m]![j] = b0 - h;
        const dn = logDetInfo(X, beta, refIdx, k, nonRef, p1, ridge);
        beta[m]![j] = b0;
        if (Number.isFinite(up) && Number.isFinite(dn)) g[d] = g[d]! + 0.5 * (up - dn) / (2 * h);
      }
    }

    const step = solveLinear(I, g);
    if (!step) break;                       // singular even with the ridge — keep the last B

    let maxStep = 0;
    for (let m = 0; m < km1; m++) {
      for (let j = 0; j < p1; j++) {
        const d = step[m * p1 + j]!;
        beta[m]![j] = beta[m]![j]! + d;
        if (Math.abs(d) > maxStep) maxStep = Math.abs(d);
      }
    }
    logLik = ll;
    if (maxStep < tol) { converged = true; break; }
  }

  // priors at the FINAL beta (the loop's last recomputation is one step behind it)
  for (let i = 0; i < n; i++) {
    const eta = new Array<number>(km1);
    for (let m = 0; m < km1; m++) {
      let acc = 0;
      for (let j = 0; j < p1; j++) acc += X[i]![j]! * beta[m]![j]!;
      eta[m] = acc;
    }
    priors[i] = priorsOf(eta, refIdx, k);
  }

  return { beta, priors, logLik, iterations, converged };
}

/**
 * Standard errors for the coefficients — by LOUIS' IDENTITY, not from the M-step.
 *
 * This is the part every two-step gets wrong, and it is easy to get wrong here too. The
 * M-step's information matrix is the COMPLETE-data information: it is what you would have if
 * you KNEW which cluster every sequence belonged to. You do not. Using it treats a sequence
 * with posterior (0.51, 0.49) as a certain member, and the standard errors come out too
 * small — the exact bias the covariate MMM exists to avoid.
 *
 * Louis (1982): observed = complete − missing, where the missing information is the
 * conditional VARIANCE of the complete-data score:
 *
 *     I_obs = sum_i x_i x_i^T ⊗ [ (diag(pi_i) − pi_i pi_i^T) − (diag(R_i) − R_i R_i^T) ]
 *
 * and it behaves exactly as it should at both extremes. Responsibilities near 0/1 (clusters
 * cleanly separated) → the missing term vanishes → the complete-data SEs, which are then
 * honest. Responsibilities near the priors (clusters not identified by the data at all) →
 * the two terms cancel → the information goes to zero and the SEs blow up, which is the
 * truth: nothing has been learned about who belongs where.
 *
 * LIMITATION, stated because it is real: this is the B-block of the information only. It
 * conditions on the transition and initial-state parameters at their MLEs and does not
 * propagate their uncertainty into B. seqHMM differentiates the whole parameter vector.
 */
export function multinomSE(
  X: number[][],
  R: number[][],
  priors: number[][],
  refIdx: number,
): { se: number[][]; ok: boolean } {
  const n = X.length;
  const p1 = n > 0 ? X[0]!.length : 0;
  const k = n > 0 ? R[0]!.length : 0;
  const km1 = k - 1;
  const nonRef: number[] = [];
  for (let c = 0; c < k; c++) if (c !== refIdx) nonRef.push(c);
  const dim = km1 * p1;

  const I: number[][] = Array.from({ length: dim }, () => new Array<number>(dim).fill(0));
  for (let i = 0; i < n; i++) {
    const xi = X[i]!, pr = priors[i]!, ri = R[i]!;
    for (let m = 0; m < km1; m++) {
      const cm = nonRef[m]!;
      for (let l = 0; l < km1; l++) {
        const cl = nonRef[l]!;
        const d = m === l ? 1 : 0;
        const complete = pr[cm]! * (d - pr[cl]!);
        const missing = ri[cm]! * (d - ri[cl]!);
        const w = complete - missing;
        if (w === 0) continue;
        for (let j = 0; j < p1; j++) {
          const xw = xi[j]! * w;
          for (let q = 0; q < p1; q++) {
            I[m * p1 + j]![l * p1 + q] = I[m * p1 + j]![l * p1 + q]! + xw * xi[q]!;
          }
        }
      }
    }
  }

  const inv = invertMatrix(I);
  const se: number[][] = Array.from({ length: km1 }, () => new Array<number>(p1).fill(NaN));
  if (!inv) return { se, ok: false };
  let ok = true;
  for (let m = 0; m < km1; m++) {
    for (let j = 0; j < p1; j++) {
      const v = inv[m * p1 + j]![m * p1 + j]!;
      if (!(v > 0)) { ok = false; se[m]![j] = NaN; }
      else se[m]![j] = Math.sqrt(v);
    }
  }
  return { se, ok };
}
